function ChatCenter({session,notify}){
 const [role,setRole]=useState('passenger'),[loading,setLoading]=useState(true),[threads,setThreads]=useState([]),[active,setActive]=useState(null),[messages,setMessages]=useState([]),[draft,setDraft]=useState(''),[busy,setBusy]=useState(false),[recording,setRecording]=useState(false),[callInfo,setCallInfo]=useState(false);
 const recorder=React.useRef(null), chunks=React.useRef([]);
 const user=session?.user;
 const loadThreads=async()=>{
  if(!user||!supabase){setLoading(false);return;}
  setLoading(true);
  const p=await supabase.from('profiles').select('requested_role').eq('id',user.id).maybeSingle();
  const currentRole=user.app_metadata?.role==='admin'?'admin':(p.data?.requested_role||'passenger');
  setRole(currentRole);
  if(currentRole==='passenger'){
   const support=await supabase.from('conversations').select('id').eq('kind','support').eq('passenger_id',user.id).maybeSingle();
   if(!support.data){await supabase.from('conversations').insert({kind:'support',passenger_id:user.id});}
   const q=await supabase.from('conversations').select('*').eq('passenger_id',user.id).order('created_at',{ascending:false});
   setThreads(q.data||[]);
  }else if(currentRole==='operator'){
   const ops=await supabase.from('operators').select('id').eq('owner_id',user.id).eq('verified',true);
   if(!ops.error&&ops.data?.length){
    for(const op of ops.data){
     const links=await supabase.from('operator_drivers').select('driver_id').eq('operator_id',op.id);
     for(const link of (links.data||[])){
      const exists=await supabase.from('conversations').select('id').eq('kind','operator_driver').eq('operator_id',op.id).eq('operator_user_id',user.id).eq('driver_user_id',link.driver_id).maybeSingle();
      if(!exists.data) await supabase.from('conversations').insert({kind:'operator_driver',operator_id:op.id,operator_user_id:user.id,driver_user_id:link.driver_id});
     }
    }
   }
   const q=await supabase.from('conversations').select('*').order('created_at',{ascending:false});
   setThreads(q.data||[]);
  }else{
   const q=await supabase.from('conversations').select('*').order('created_at',{ascending:false});
   setThreads(q.data||[]);
  }
  setLoading(false);
 };
 useEffect(()=>{loadThreads()},[user?.id]);
 useEffect(()=>{
  if(!active)return;
  const load=async()=>{const r=await supabase.from('messages').select('*').eq('conversation_id',active.id).order('created_at');if(!r.error){setMessages(r.data||[]);const unread=(r.data||[]).filter(m=>m.sender_id!==user.id&&!m.read_at);if(unread.length)await supabase.from('messages').update({read_at:new Date().toISOString()}).in('id',unread.map(m=>m.id));}};
  load();
  const ch=supabase.channel('trip-chat-'+active.id).on('postgres_changes',{event:'*',schema:'public',table:'messages',filter:'conversation_id=eq.'+active.id},()=>load()).subscribe();
  return()=>{supabase.removeChannel(ch)};
 },[active?.id,user?.id]);
 const sendText=async(e)=>{e?.preventDefault();if(!draft.trim()||!active||busy)return;setBusy(true);const r=await supabase.from('messages').insert({conversation_id:active.id,sender_id:user.id,message_type:'text',body:draft.trim()});setBusy(false);if(r.error){notify('تعذر إرسال الرسالة: '+r.error.message);return}setDraft('')};
 const startRecording=async()=>{
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('تسجيل الصوت غير مدعوم في هذا المتصفح');return}
  try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const mr=new MediaRecorder(stream);recorder.current=mr;chunks.current=[];mr.ondataavailable=e=>{if(e.data.size)chunks.current.push(e.data)};mr.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(chunks.current,{type:mr.mimeType||'audio/webm'});if(!blob.size||!active)return;setBusy(true);const mime=(blob.type||'audio/webm').split(';')[0];const ext=(mime.split('/')[1]||'webm');const path=active.id+'/'+crypto.randomUUID()+'.'+ext;const up=await supabase.storage.from('trip-chat-media').upload(path,blob,{contentType:mime,upsert:false});if(up.error){setBusy(false);notify('تعذر رفع التسجيل الصوتي: '+up.error.message);return}const ins=await supabase.from('messages').insert({conversation_id:active.id,sender_id:user.id,message_type:'voice',storage_path:path});setBusy(false);if(ins.error)notify('تم رفع الصوت لكن تعذر حفظ الرسالة: '+ins.error.message);};mr.start();setRecording(true)}catch(err){notify('لم نتمكن من استخدام الميكروفون. تحقق من إذن المتصفح.')}
 };
 const stopRecording=()=>{if(recorder.current&&recorder.current.state!=='inactive'){recorder.current.stop();setRecording(false)}};
 const titleFor=(c)=>c.kind==='support'?'الدعم الفني – إدارة TRIP':c.kind==='booking_operator'?'شركة النقل · حجز '+(c.booking_id||'').slice(0,8):c.kind==='booking_driver'?'السائق · حجز '+(c.booking_id||'').slice(0,8):'محادثة الشركة والسائق';
 return <main className="content chatPage" dir="rtl">
  <div className="chatHeading"><div><span className="eyebrow green">مركز التواصل</span><h1>محادثات TRIP</h1><p className="muted">{role==='passenger'?'الدعم متاح دائماً، ومحادثات الشركة والسائق تظهر بعد تأكيد الدفع.':'محادثات الأطراف المصرح بها حسب صلاحيات الحساب.'}</p></div><button className="outline" onClick={loadThreads}>تحديث</button></div>
  {loading?<div className="empty">جارٍ تحميل المحادثات…</div>:<div className="chatShell">
   <aside className="chatSidebar"><div className="chatSideTitle">المحادثات <span>{threads.length}</span></div>{threads.length?threads.map(c=><button key={c.id} className={'chatThread '+(active?.id===c.id?'active':'')} onClick={()=>setActive(c)}><span className="chatAvatar">{c.kind==='support'?'TR':'↔'}</span><span><b>{titleFor(c)}</b><small>{new Date(c.created_at).toLocaleDateString('ar-SD')}</small></span></button>):<div className="chatEmpty">لا توجد محادثات متاحة لهذا الحساب حالياً.</div>}</aside>
   <section className="chatConversation">{active?<><div className="chatTop"><div><b>{titleFor(active)}</b><small>{active.kind==='support'?'الراكب ↔ الإدارة فقط':'الشركة ↔ السائق فقط'}</small></div><button className="callButton" onClick={()=>setCallInfo(true)}><Phone size={17}/> اتصال صوتي</button></div>
    <div className="chatMessages">{messages.length?messages.map(m=><MessageBubble key={m.id} message={m} mine={m.sender_id===user.id}/>):<div className="chatBlank"><MessageCircle size={34}/><b>ابدأ المحادثة</b><small>أرسل رسالة إلى الطرف المصرح له في هذه المحادثة.</small></div>}</div>
    <form className="chatComposer" onSubmit={sendText}><button type="button" className={'voiceButton '+(recording?'recording':'')} disabled={busy} onClick={recording?stopRecording:startRecording} title={recording?'إيقاف التسجيل':'تسجيل رسالة صوتية'}>{recording?<Square size={18}/>:<Mic size={18}/>}</button><input value={draft} onChange={e=>setDraft(e.target.value)} placeholder="اكتب رسالتك هنا…" disabled={busy}/><button className="sendButton" disabled={busy||!draft.trim()}><Send size={18}/></button></form>
    {recording&&<div className="recordHint">جارٍ التسجيل… اضغط المربع لإيقاف التسجيل وإرساله</div>}
   </>:<div className="chatBlank"><MessageCircle size={42}/><b>اختر محادثة</b><small>ستظهر الرسائل هنا بشكل مباشر.</small></div>}</section>
  </div>}
  {callInfo&&<div className="modalShade" onClick={()=>setCallInfo(false)}><div className="tripModal callInfoModal" onClick={e=>e.stopPropagation()}><div className="modalHead"><h2>الاتصال الصوتي</h2><button className="closeModal" onClick={()=>setCallInfo(false)}><X/></button></div><p>واجهة الاتصال جاهزة للتصميم، لكن المكالمات المباشرة تحتاج إعداد خدمة اتصال آمنة وإشارات WebRTC على الخادم. لم نفعّل الاتصال بعد حتى لا يظهر زر يوهم المستخدم بأن المكالمة تعمل.</p><button className="primary full" onClick={()=>setCallInfo(false)}>حسناً</button></div></div>}
 </main>
}
function DriverDashboard({session,notify}){
 const user=session?.user;
 const [rows,setRows]=useState([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[sharingTrip,setSharingTrip]=useState(''),[lastPosition,setLastPosition]=useState(null);
 const watchRef=React.useRef(null);
 const load=async()=>{
  if(!user||!supabase){setLoading(false);return}
  setLoading(true);
  const r=await supabase.from('trips').select('id,origin_city,destination_city,origin_terminal,destination_terminal,departure_at,arrival_at,status,driver_id,buses(name,plate_number,seat_count),operators(name,phone)').eq('driver_id',user.id).order('departure_at',{ascending:false});
  if(r.error)notify('تعذر تحميل رحلات السائق: '+r.error.message);
  setRows(r.data||[]);setLoading(false);
 };
 useEffect(()=>{load();return()=>{if(watchRef.current!==null&&navigator.geolocation)navigator.geolocation.clearWatch(watchRef.current)}},[user?.id]);
 const changeStatus=async(t,status)=>{
  setBusy(true);const r=await supabase.rpc('driver_update_trip_status',{p_trip_id:t.id,p_status:status});setBusy(false);
  if(r.error){notify('تعذر تحديث حالة الرحلة: '+r.error.message);return}
  notify('تم تحديث حالة الرحلة');load();
 };
 const stopSharing=()=>{if(watchRef.current!==null&&navigator.geolocation){navigator.geolocation.clearWatch(watchRef.current);watchRef.current=null}setSharingTrip('');notify('تم إيقاف مشاركة الموقع')};
 const startSharing=(t)=>{
  if(!navigator.geolocation){notify('المتصفح لا يدعم تحديد الموقع');return}
  if(watchRef.current!==null)navigator.geolocation.clearWatch(watchRef.current);
  setSharingTrip(t.id);
  watchRef.current=navigator.geolocation.watchPosition(async pos=>{
   const point={trip_id:t.id,driver_id:user.id,latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy_m:pos.coords.accuracy,updated_at:new Date().toISOString()};
   const saved=await supabase.from('driver_trip_locations').upsert(point,{onConflict:'trip_id'});
   if(saved.error){notify('تعذر تحديث الموقع: '+saved.error.message);stopSharing();return}
   setLastPosition({tripId:t.id,lat:point.latitude,lng:point.longitude,updatedAt:point.updated_at});
  },err=>{notify(err.code===1?'اسمح للتطبيق بالوصول إلى الموقع لبدء المشاركة.':'تعذر تحديد موقعك. تحقق من GPS والإنترنت.');stopSharing()},{enableHighAccuracy:true,maximumAge:5000,timeout:20000});
 };
 if(!user)return <main className="content narrow"><div className="empty"><h2>سجّل الدخول أولاً</h2><p>لوحة السائق مخصصة لحسابات السائقين المعتمدة.</p></div></main>;
 return <main className="content">
  <div className="adminHead"><div><span className="eyebrow green">بوابة السائق</span><h1>رحلاتي ومشاركة الموقع</h1><p className="muted">تابع الرحلات المسندة إليك وحدّث حالتها وشارك موقع الباص أثناء الرحلة.</p></div><button className="outline" onClick={load} disabled={loading}>تحديث</button></div>
  {loading?<div className="empty">جارٍ تحميل الرحلات…</div>:rows.length? <div className="tripList">{rows.map(t=><article className="trip driverTrip" key={t.id}>
   <div className="driverTripHead"><div><b>{t.origin_city} ← {t.destination_city}</b><small>{t.origin_terminal||'موقف المغادرة غير محدد'} ← {t.destination_terminal||'موقف الوصول غير محدد'}</small><small>{new Date(t.departure_at).toLocaleString('ar-SD')} · {t.buses?.name||'الباص'} · {t.buses?.plate_number||'—'}</small><small>شركة النقل: {t.operators?.name||'—'}</small></div><span className="status">{t.status}</span></div>
   <div className="driverTripActions">
    {t.status==='scheduled'&&<button className="primary" disabled={busy} onClick={()=>changeStatus(t,'boarding')}>بدء الصعود</button>}
    {t.status==='boarding'&&<button className="primary" disabled={busy} onClick={()=>changeStatus(t,'departed')}>انطلاق الباص</button>}
    {t.status==='departed'&&<button className="primary" disabled={busy} onClick={()=>changeStatus(t,'completed')}>إكمال الرحلة</button>}
    {['boarding','departed'].includes(t.status)&&<button className="outline" onClick={()=>sharingTrip===t.id?stopSharing():startSharing(t)}><MapPin size={16}/>{sharingTrip===t.id?'إيقاف مشاركة الموقع':'مشاركة موقعي'}</button>}
    {t.operators?.phone&&<a className="outline" href={'tel:'+t.operators.phone}><Phone size={16}/> الاتصال بالشركة</a>}
   </div>
   {sharingTrip===t.id&&<div className="driverLocationStatus"><span className="liveDot"></span> مشاركة الموقع مفعّلة {lastPosition?.tripId===t.id?'· تم تحديث موقعك':''}{lastPosition?.tripId===t.id&&<a href={'https://www.google.com/maps?q='+lastPosition.lat+','+lastPosition.lng} target="_blank" rel="noreferrer">عرض موقعي على الخريطة</a>}</div>}
  </article>)}</div>:<div className="empty"><Bus size={38}/><h3>لا توجد رحلات مسندة إليك</h3><p>ستظهر الرحلات هنا بعد ربط حسابك بالشركة وتعيينك سائقاً لرحلة.</p></div>}
 </main>
}
function ParcelOperations({operatorId=null,isAdmin=false,notify}){
 const [rows,setRows]=useState([]),[companies,setCompanies]=useState([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');
 const statuses=[['pending','بانتظار المراجعة'],['accepted','تم قبول الطلب'],['picked_up','تم استلام الطرد'],['in_transit','في الطريق'],['delivered','تم التسليم'],['cancelled','ملغي']];
 const load=async()=>{
  setLoading(true);
  let q=supabase.from('parcels').select('id,tracking_code,sender_name,sender_phone,receiver_name,receiver_phone,origin_city,destination_city,description,status,operator_id,price_sdg,created_at,operators(name)').order('created_at',{ascending:false});
  if(operatorId)q=q.eq('operator_id',operatorId);
  const [p,o]=await Promise.all([q,isAdmin?supabase.from('operators').select('id,name').order('name'):Promise.resolve({data:[],error:null})]);
  if(p.error)notify('تعذر تحميل طلبات الطرود: '+p.error.message);
  setRows(p.data||[]);setCompanies(o.data||[]);setLoading(false);
 };
 useEffect(()=>{load()},[operatorId,isAdmin]);
 const updateParcel=async(p,patch)=>{
  setBusy(p.id);const r=await supabase.from('parcels').update({...patch,updated_at:new Date().toISOString()}).eq('id',p.id);setBusy('');
  if(r.error){notify('تعذر تحديث طلب الشحن: '+r.error.message);return}
  notify('تم تحديث طلب الشحن');load();
 };
 return <section><div className="sectionHead"><div><h2>{isAdmin?'إدارة شحن الطرود':'طلبات الطرود التابعة للشركة'}</h2><p className="muted">متابعة رقم التتبع وحالة الاستلام والتوصيل.</p></div><button className="outline" onClick={load} disabled={loading}>تحديث</button></div>
 {loading?<div className="empty">جارٍ تحميل الطلبات…</div>:rows.length?<div className="tableWrap"><table><thead><tr><th>رقم التتبع</th><th>المسار</th><th>المرسل / المستلم</th><th>الشركة</th><th>الحالة</th><th>قيمة الشحن</th><th>إجراء</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><b>{p.tracking_code||p.id.slice(0,8)}</b><small>{new Date(p.created_at).toLocaleDateString('ar-SD')}</small></td><td>{p.origin_city} ← {p.destination_city}<small>{p.description||'—'}</small></td><td>{p.sender_name}<small>{p.sender_phone}</small><small>إلى: {p.receiver_name} · {p.receiver_phone}</small></td><td>{p.operators?.name||'غير مسندة'}</td><td><select value={p.status||'pending'} disabled={busy===p.id} onChange={e=>updateParcel(p,{status:e.target.value})}>{statuses.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></td><td>{p.price_sdg?money(Number(p.price_sdg)):'—'}</td><td>{isAdmin?<select value={p.operator_id||''} disabled={busy===p.id} onChange={e=>updateParcel(p,{operator_id:e.target.value||null})}><option value="">إسناد لشركة</option>{companies.map(o=><option value={o.id} key={o.id}>{o.name}</option>)}</select>:<span className="muted">تحديث الحالة</span>}</td></tr>)}</tbody></table></div>:<div className="empty"><Package size={36}/><h3>لا توجد طلبات شحن</h3><p>{isAdmin?'ستظهر طلبات الركاب هنا لتعيين شركة النقل ومتابعة التنفيذ.':'ستظهر الطلبات التي أسندتها إدارة المنصة إلى شركتك.'}</p></div>}
 </section>
}
