function AdminCompanySubscriptions({session,notify}){
 const [rows,setRows]=useState([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState('');
 const load=async()=>{setLoading(true);const r=await supabase.from('operator_subscriptions').select('*,operators(id,name,phone,verified)').order('created_at',{ascending:false});if(r.error)notify('تعذر تحميل طلبات الاشتراك: '+r.error.message);setRows(r.data||[]);setLoading(false)};
 useEffect(()=>{load()},[]);
 const approve=async(row)=>{
  setBusy(row.id);
  const op=await supabase.from('operators').update({verified:true}).eq('id',row.operator_id);
  if(op.error){setBusy('');notify('تعذر اعتماد الشركة: '+op.error.message);return}
  const now=new Date(),end=new Date(now.getTime()+30*24*60*60*1000);
  const sub=await supabase.from('operator_subscriptions').update({status:'active',starts_at:now.toISOString(),ends_at:end.toISOString(),reviewed_by:session.user.id,reviewed_at:now.toISOString()}).eq('id',row.id);
  setBusy('');
  if(sub.error){notify('تم اعتماد الشركة لكن تعذر تفعيل الاشتراك: '+sub.error.message);return}
  notify('تم اعتماد الشركة وتفعيل اشتراكها لمدة 30 يوماً');load();
 };
 const reject=async(row)=>{setBusy(row.id);const r=await supabase.from('operator_subscriptions').update({status:'rejected',reviewed_by:session.user.id,reviewed_at:new Date().toISOString()}).eq('id',row.id);setBusy('');if(r.error){notify('تعذر رفض الطلب: '+r.error.message);return}notify('تم رفض طلب الاشتراك');load()};
 if(loading)return <div className="empty">جارٍ تحميل طلبات الشركات…</div>;
 if(!rows.length)return <div className="empty">لا توجد طلبات اشتراك حتى الآن.</div>;
 return <div className="tableWrap"><table><thead><tr><th>الشركة</th><th>الهاتف</th><th>قيمة الاشتراك</th><th>مرجع الدفع</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{rows.map(row=><tr key={row.id}><td>{row.operators?.name||'شركة غير معروفة'}</td><td>{row.operators?.phone||'—'}</td><td>{money(Number(row.amount_sdg))}</td><td>{row.payment_reference||'—'}<small>{row.payment_note||''}</small></td><td>{row.status}</td><td>{row.status==='pending'?<div className="modalActions"><button className="primary" disabled={busy===row.id} onClick={()=>approve(row)}>اعتماد وتفعيل</button><button className="outline" disabled={busy===row.id} onClick={()=>reject(row)}>رفض</button></div>:<span>{row.operators?.verified?'الشركة معتمدة':'بانتظار اعتماد الشركة'}</span>}</td></tr>)}</tbody></table></div>;
}


